BEGIN;
DO $pre$ BEGIN
 IF (SELECT count(*) FROM public.character_abilities WHERE technique_id=ANY(ARRAY['496e638a-93ad-48da-b982-054edaca9073'::uuid,'5a691ee7-4f10-4239-bc6d-2a21c479d411'::uuid,'abd85ea4-5a85-4696-b9bd-758315f9c814'::uuid,'0b2cac25-aae6-4f0d-a182-985f57cf3586'::uuid,'42f1b6a7-04cd-4430-a5d9-637769bc9ecb'::uuid,'43f0e810-33d1-4aa0-8dcc-12654304dff0'::uuid,'e688acac-57c0-4c0f-8ea5-3b8a976ecc04'::uuid,'f1440a58-ee95-53dc-8ed5-a53543d970ce'::uuid,'f0fdbc8e-5cf3-5c9b-af2a-e52869fa8dfc'::uuid,'65719592-7de9-5aa1-8d59-e8da2338d45b'::uuid,'96927a19-9908-59da-9f17-2611e031bd8d'::uuid,'9ac77d79-9894-5388-9753-70538ac5eaa3'::uuid]))<>0 THEN RAISE EXCEPTION 'taijutsu_rights_acquired'; END IF;
 IF (SELECT count(*) FROM public.training_sessions WHERE technique_id=ANY(ARRAY['496e638a-93ad-48da-b982-054edaca9073'::uuid,'5a691ee7-4f10-4239-bc6d-2a21c479d411'::uuid,'abd85ea4-5a85-4696-b9bd-758315f9c814'::uuid,'0b2cac25-aae6-4f0d-a182-985f57cf3586'::uuid,'42f1b6a7-04cd-4430-a5d9-637769bc9ecb'::uuid,'43f0e810-33d1-4aa0-8dcc-12654304dff0'::uuid,'e688acac-57c0-4c0f-8ea5-3b8a976ecc04'::uuid,'f1440a58-ee95-53dc-8ed5-a53543d970ce'::uuid,'f0fdbc8e-5cf3-5c9b-af2a-e52869fa8dfc'::uuid,'65719592-7de9-5aa1-8d59-e8da2338d45b'::uuid,'96927a19-9908-59da-9f17-2611e031bd8d'::uuid,'9ac77d79-9894-5388-9753-70538ac5eaa3'::uuid]))<>0 THEN RAISE EXCEPTION 'taijutsu_training_started'; END IF;
 IF (SELECT count(*) FROM (VALUES ('b10f8ee7-43ed-4de1-8662-bfcc08ea3a07'::uuid,'Dopo aver composto i sigilli, iniziando dall’Uccello, il ninja concentra il chakra Vento sul filo della mano e lo libera in una sottile lama d’aria. Se raggiunge l’avversario, la pressione può incidere pelle e tessuti lasciando tagli netti.','La Parata è meno efficace contro la lama d’aria. Schivata, Sostituzione e tecniche difensive mantengono la loro normale efficacia.'),('72cbe1fb-34c8-44c7-a053-0014b4894b3e'::uuid,'Dopo il sigillo della Lepre, il ninja raccoglie il chakra Fulmine nel palmo e lo libera al contatto in una scarica breve e concentrata. L’urto elettrico attraversa la parte colpita con un lampo secco e può lasciare i muscoli momentaneamente intorpiditi.','Parata e Schivata successive possono risultare più difficili. Sostituzione e tecniche difensive conservano la loro normale efficacia e non consumano l’apertura.'),('29e49eb9-56d7-4d35-afae-af14bf0c8e65'::uuid,'Dopo il sigillo della Lepre, il ninja comprime il chakra Fulmine in una lancia sottile e luminosa, quindi la scaglia lungo una traiettoria diretta. Il lampo attraversa rapidamente lo spazio e scarica la propria energia nel punto raggiunto.','La Schivata è meno efficace contro la rapidità della lancia. Parata, Sostituzione e tecniche difensive mantengono la loro normale efficacia.'),('fea014d1-0d71-43dd-bd60-045fbecf3184'::uuid,'Dopo il sigillo del Serpente, il ninja concentra il chakra Terra e forma un proiettile di roccia compatto, che scaglia contro l’avversario con un impatto pesante e concentrato.','La Parata assorbe meno efficacemente la forza dell’impatto. Schivata, Sostituzione e tecniche difensive mantengono la loro normale efficacia.'),('f1440a58-ee95-53dc-8ed5-a53543d970ce'::uuid,'Il ninja apre con un calcio ascendente, incalza l’avversario con una rapida concatenazione di colpi ravvicinati e chiude con un calcio discendente verso terra. I diversi colpi compongono un’unica scena offensiva e rappresentano una sola tecnica continua, non azioni separate.','La difesa conserva tutte le normali possibilità contro l’intera sequenza.'),('f0fdbc8e-5cf3-5c9b-af2a-e52869fa8dfc'::uuid,'Il ninja abbassa il baricentro e ruota rapidamente, distendendo la gamba contro gli appoggi dell’avversario. Il calcio basso cerca di spezzarne per un istante l’equilibrio e il passo.','La difesa può evitare o attenuare normalmente il colpo. Soltanto un impatto pieno compromette temporaneamente il movimento del bersaglio.'),('65719592-7de9-5aa1-8d59-e8da2338d45b'::uuid,'Il ninja entra in rotazione con un calcio alto che impegna la guardia e prosegue nello stesso movimento con un secondo calcio basso. Le due traiettorie compongono un’unica scena offensiva e una sola tecnica continua.','La Parata è meno efficace contro il rapido cambio d’altezza dei due calci. Schivata, Sostituzione e tecniche difensive mantengono la loro normale efficacia.'),('96927a19-9908-59da-9f17-2611e031bd8d'::uuid,'Il ninja raccoglie il corpo e libera dal basso un calcio ascendente diretto al busto o al mento dell’avversario. L’impatto cerca di sollevarne la postura e di aprire la guardia, mentre l’esecutore ricade nella stessa sequenza.','Un colpo pieno può rendere più difficile la prima Parata o Schivata successiva. Sostituzione e tecniche difensive restano pienamente efficaci e non consumano l’apertura.'),('9ac77d79-9894-5388-9753-70538ac5eaa3'::uuid,'Il ninja scatta in linea retta verso l’avversario, trasforma la rincorsa in uno slancio e conclude l’avvicinamento con un calcio volante frontale. La tecnica unisce corsa e impatto in un solo gesto continuo.','Dopo una rincorsa valida, Parata e Schivata sono meno efficaci contro l’impeto del calcio. Sostituzione e tecniche difensive mantengono la loro normale efficacia.')) v(id,description,effect) JOIN public.clan_techniques c ON c.id=v.id AND c.description=v.description AND c.danno_effetto=v.effect WHERE c.is_active)<>9 THEN RAISE EXCEPTION 'installed_catalog_drift'; END IF;
 IF (SELECT count(*) FROM public.clan_techniques WHERE id=ANY(ARRAY['496e638a-93ad-48da-b982-054edaca9073'::uuid,'5a691ee7-4f10-4239-bc6d-2a21c479d411'::uuid,'abd85ea4-5a85-4696-b9bd-758315f9c814'::uuid,'0b2cac25-aae6-4f0d-a182-985f57cf3586'::uuid,'42f1b6a7-04cd-4430-a5d9-637769bc9ecb'::uuid,'43f0e810-33d1-4aa0-8dcc-12654304dff0'::uuid,'e688acac-57c0-4c0f-8ea5-3b8a976ecc04'::uuid]) AND NOT is_active)<>7 THEN RAISE EXCEPTION 'legacy_state_drift'; END IF;
 IF (SELECT count(*) FROM combat_v2_elemental_internal.other_gates WHERE technique_id=ANY(ARRAY['b10f8ee7-43ed-4de1-8662-bfcc08ea3a07'::uuid,'72cbe1fb-34c8-44c7-a053-0014b4894b3e'::uuid,'29e49eb9-56d7-4d35-afae-af14bf0c8e65'::uuid,'fea014d1-0d71-43dd-bd60-045fbecf3184'::uuid]) AND enabled AND public_enabled)<>4 THEN RAISE EXCEPTION 'elemental_gate_drift'; END IF;
 IF (SELECT count(*) FROM combat_v2_taijutsu_internal.taijutsu_gates WHERE technique_id=ANY(ARRAY['f1440a58-ee95-53dc-8ed5-a53543d970ce'::uuid,'f0fdbc8e-5cf3-5c9b-af2a-e52869fa8dfc'::uuid,'65719592-7de9-5aa1-8d59-e8da2338d45b'::uuid,'96927a19-9908-59da-9f17-2611e031bd8d'::uuid,'9ac77d79-9894-5388-9753-70538ac5eaa3'::uuid]) AND staff_enabled AND public_enabled)<>5 THEN RAISE EXCEPTION 'taijutsu_gate_drift'; END IF;
END $pre$;
UPDATE public.clan_techniques SET description='Un taglio d''aria compressa sul filo della mano. Non lascia lividi: lascia tagli netti. Si apre col sigillo dell''Uccello.',danno_effetto='Colpo ravvicinato che taglia invece di contundere.' WHERE id='b10f8ee7-43ed-4de1-8662-bfcc08ea3a07'::uuid;
UPDATE public.clan_techniques SET description='Una scossa secca a mano aperta. Fa più male di quanto sembri. Si apre col sigillo della Lepre.',danno_effetto='Intorpidisce il braccio colpito per il resto del turno.' WHERE id='72cbe1fb-34c8-44c7-a053-0014b4894b3e'::uuid;
UPDATE public.clan_techniques SET description='Un dardo che parte dritto e arriva prima che l''occhio lo segua. Si apre col sigillo della Lepre.',danno_effetto='Chi ha Velocità bassa fatica a schivarlo.' WHERE id='29e49eb9-56d7-4d35-afae-af14bf0c8e65'::uuid;
UPDATE public.clan_techniques SET description='Strappi una scheggia di terreno e la scagli. Rozzo, pesante, difficile da deviare. Si apre col sigillo del Serpente.',danno_effetto='Colpo pesante a distanza media.' WHERE id='fea014d1-0d71-43dd-bd60-045fbecf3184'::uuid;
UPDATE public.clan_techniques SET description='Un calcio ascendente apre l’inseguimento ravvicinato; una concatenazione di calci culmina nella chiusura verso terra.',danno_effetto='Un solo confronto e un solo pacchetto. La difesa conserva tutte le normali opzioni.',is_active=false WHERE id='f1440a58-ee95-53dc-8ed5-a53543d970ce'::uuid;
UPDATE public.clan_techniques SET description='Una rotazione bassa porta il calcio contro gli appoggi del bersaglio per sottrargli equilibrio.',danno_effetto='Se il colpo è pieno, il bersaglio dispone di 2 metri in meno nel proprio turno successivo. La difesa può evitare o ridurre l’esito secondo le regole ordinarie.',is_active=false WHERE id='f0fdbc8e-5cf3-5c9b-af2a-e52869fa8dfc'::uuid;
UPDATE public.clan_techniques SET description='Un calcio alto impegna la guardia, seguito da un calcio basso nella stessa rotazione.',danno_effetto='Contro Parata la tecnica è più difficile da fermare. Schivata, Sostituzione e tecniche difensive non subiscono questo vantaggio.',is_active=false WHERE id='65719592-7de9-5aa1-8d59-e8da2338d45b'::uuid;
UPDATE public.clan_techniques SET description='Il ninja raccoglie il corpo e libera un calcio ascendente, ricadendo nella medesima sequenza.',danno_effetto='Un colpo pieno apre per un istante la guardia del bersaglio: la prima Parata o Schivata successiva risulta più difficile. Sostituzione e tecniche difensive non consumano l’apertura.',is_active=false WHERE id='96927a19-9908-59da-9f17-2611e031bd8d'::uuid;
UPDATE public.clan_techniques SET description='Una rincorsa rettilinea si conclude con un calcio volante frontale contro il bersaglio.',danno_effetto='La rincorsa rende il colpo più difficile da fermare con Parata o Schivata. Se il percorso non è valido, la tecnica non può essere scelta.',is_active=false WHERE id='9ac77d79-9894-5388-9753-70538ac5eaa3'::uuid;
UPDATE public.clan_techniques SET is_active=true WHERE id=ANY(ARRAY['496e638a-93ad-48da-b982-054edaca9073'::uuid,'5a691ee7-4f10-4239-bc6d-2a21c479d411'::uuid,'abd85ea4-5a85-4696-b9bd-758315f9c814'::uuid,'0b2cac25-aae6-4f0d-a182-985f57cf3586'::uuid,'42f1b6a7-04cd-4430-a5d9-637769bc9ecb'::uuid,'43f0e810-33d1-4aa0-8dcc-12654304dff0'::uuid,'e688acac-57c0-4c0f-8ea5-3b8a976ecc04'::uuid]);
UPDATE combat_v2_elemental_internal.other_gates SET public_enabled=false WHERE technique_id=ANY(ARRAY['b10f8ee7-43ed-4de1-8662-bfcc08ea3a07'::uuid,'72cbe1fb-34c8-44c7-a053-0014b4894b3e'::uuid,'29e49eb9-56d7-4d35-afae-af14bf0c8e65'::uuid,'fea014d1-0d71-43dd-bd60-045fbecf3184'::uuid]);
UPDATE combat_v2_taijutsu_internal.taijutsu_gates SET public_enabled=false WHERE technique_id=ANY(ARRAY['f1440a58-ee95-53dc-8ed5-a53543d970ce'::uuid,'f0fdbc8e-5cf3-5c9b-af2a-e52869fa8dfc'::uuid,'65719592-7de9-5aa1-8d59-e8da2338d45b'::uuid,'96927a19-9908-59da-9f17-2611e031bd8d'::uuid,'9ac77d79-9894-5388-9753-70538ac5eaa3'::uuid]);
DO $post$ BEGIN
 IF (SELECT count(*) FROM (VALUES ('b10f8ee7-43ed-4de1-8662-bfcc08ea3a07'::uuid,'Un taglio d''aria compressa sul filo della mano. Non lascia lividi: lascia tagli netti. Si apre col sigillo dell''Uccello.','Colpo ravvicinato che taglia invece di contundere.'),('72cbe1fb-34c8-44c7-a053-0014b4894b3e'::uuid,'Una scossa secca a mano aperta. Fa più male di quanto sembri. Si apre col sigillo della Lepre.','Intorpidisce il braccio colpito per il resto del turno.'),('29e49eb9-56d7-4d35-afae-af14bf0c8e65'::uuid,'Un dardo che parte dritto e arriva prima che l''occhio lo segua. Si apre col sigillo della Lepre.','Chi ha Velocità bassa fatica a schivarlo.'),('fea014d1-0d71-43dd-bd60-045fbecf3184'::uuid,'Strappi una scheggia di terreno e la scagli. Rozzo, pesante, difficile da deviare. Si apre col sigillo del Serpente.','Colpo pesante a distanza media.'),('f1440a58-ee95-53dc-8ed5-a53543d970ce'::uuid,'Un calcio ascendente apre l’inseguimento ravvicinato; una concatenazione di calci culmina nella chiusura verso terra.','Un solo confronto e un solo pacchetto. La difesa conserva tutte le normali opzioni.'),('f0fdbc8e-5cf3-5c9b-af2a-e52869fa8dfc'::uuid,'Una rotazione bassa porta il calcio contro gli appoggi del bersaglio per sottrargli equilibrio.','Se il colpo è pieno, il bersaglio dispone di 2 metri in meno nel proprio turno successivo. La difesa può evitare o ridurre l’esito secondo le regole ordinarie.'),('65719592-7de9-5aa1-8d59-e8da2338d45b'::uuid,'Un calcio alto impegna la guardia, seguito da un calcio basso nella stessa rotazione.','Contro Parata la tecnica è più difficile da fermare. Schivata, Sostituzione e tecniche difensive non subiscono questo vantaggio.'),('96927a19-9908-59da-9f17-2611e031bd8d'::uuid,'Il ninja raccoglie il corpo e libera un calcio ascendente, ricadendo nella medesima sequenza.','Un colpo pieno apre per un istante la guardia del bersaglio: la prima Parata o Schivata successiva risulta più difficile. Sostituzione e tecniche difensive non consumano l’apertura.'),('9ac77d79-9894-5388-9753-70538ac5eaa3'::uuid,'Una rincorsa rettilinea si conclude con un calcio volante frontale contro il bersaglio.','La rincorsa rende il colpo più difficile da fermare con Parata o Schivata. Se il percorso non è valido, la tecnica non può essere scelta.')) v(id,description,effect) JOIN public.clan_techniques c ON c.id=v.id AND c.description=v.description AND c.danno_effetto=v.effect)<>9 THEN RAISE EXCEPTION 'catalog_recovery_postflight'; END IF;
 IF (SELECT count(*) FROM public.clan_techniques WHERE id=ANY(ARRAY['b10f8ee7-43ed-4de1-8662-bfcc08ea3a07'::uuid,'72cbe1fb-34c8-44c7-a053-0014b4894b3e'::uuid,'29e49eb9-56d7-4d35-afae-af14bf0c8e65'::uuid,'fea014d1-0d71-43dd-bd60-045fbecf3184'::uuid,'496e638a-93ad-48da-b982-054edaca9073'::uuid,'5a691ee7-4f10-4239-bc6d-2a21c479d411'::uuid,'abd85ea4-5a85-4696-b9bd-758315f9c814'::uuid,'0b2cac25-aae6-4f0d-a182-985f57cf3586'::uuid,'42f1b6a7-04cd-4430-a5d9-637769bc9ecb'::uuid,'43f0e810-33d1-4aa0-8dcc-12654304dff0'::uuid,'e688acac-57c0-4c0f-8ea5-3b8a976ecc04'::uuid]) AND is_active)<>11 THEN RAISE EXCEPTION 'active_recovery_postflight'; END IF;
 IF (SELECT count(*) FROM public.clan_techniques WHERE id=ANY(ARRAY['f1440a58-ee95-53dc-8ed5-a53543d970ce'::uuid,'f0fdbc8e-5cf3-5c9b-af2a-e52869fa8dfc'::uuid,'65719592-7de9-5aa1-8d59-e8da2338d45b'::uuid,'96927a19-9908-59da-9f17-2611e031bd8d'::uuid,'9ac77d79-9894-5388-9753-70538ac5eaa3'::uuid]) AND NOT is_active)<>5 THEN RAISE EXCEPTION 'taijutsu_recovery_postflight'; END IF;
 IF (SELECT count(*) FROM combat_v2_elemental_internal.other_gates WHERE technique_id=ANY(ARRAY['b10f8ee7-43ed-4de1-8662-bfcc08ea3a07'::uuid,'72cbe1fb-34c8-44c7-a053-0014b4894b3e'::uuid,'29e49eb9-56d7-4d35-afae-af14bf0c8e65'::uuid,'fea014d1-0d71-43dd-bd60-045fbecf3184'::uuid]) AND enabled AND NOT public_enabled)<>4 THEN RAISE EXCEPTION 'elemental_gate_recovery_postflight'; END IF;
 IF (SELECT count(*) FROM combat_v2_taijutsu_internal.taijutsu_gates WHERE technique_id=ANY(ARRAY['f1440a58-ee95-53dc-8ed5-a53543d970ce'::uuid,'f0fdbc8e-5cf3-5c9b-af2a-e52869fa8dfc'::uuid,'65719592-7de9-5aa1-8d59-e8da2338d45b'::uuid,'96927a19-9908-59da-9f17-2611e031bd8d'::uuid,'9ac77d79-9894-5388-9753-70538ac5eaa3'::uuid]) AND staff_enabled AND NOT public_enabled)<>5 THEN RAISE EXCEPTION 'taijutsu_gate_recovery_postflight'; END IF;
END $post$;
COMMIT;
